describe('File Upload Retry Without Re-selection', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully retry a failed upload without re-selecting the file', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('uploadFailed');

    // Attempt to upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Verify initial upload attempt was made
    cy.wait('@uploadFailed');
    cy.get('[data-testid="upload-status"]').should('contain', 'Failed');
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Server error');

    // Retry button should be visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry was triggered
    cy.wait('@uploadFailed');

    // Verify error message is still visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify file input still has the same file selected
    cy.get('[data-testid="file-input"]').should('have.value', 'cypress/fixtures/test-file.pdf');

    // Verify retry button is still visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button again
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry was successful
    cy.wait('@uploadFailed');
    cy.get('[data-testid="upload-status"]').should('contain', 'Success');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file was uploaded
    cy.get('[data-testid="uploaded-files"]').should('contain', 'test-file.pdf');
  });

  it('should handle retry when file is already selected and upload fails', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('uploadFailed');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });

    // Verify file is selected
    cy.get('[data-testid="file-input"]').should('have.value', 'cypress/fixtures/test-file.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Verify initial upload attempt was made
    cy.wait('@uploadFailed');
    cy.get('[data-testid="upload-status"]').should('contain', 'Failed');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry was triggered
    cy.wait('@uploadFailed');

    // Verify error message is still visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify retry button is still visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button again
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry was successful
    cy.wait('@uploadFailed');
    cy.get('[data-testid="upload-status"]').should('contain', 'Success');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file was uploaded
    cy.get('[data-testid="uploaded-files"]').should('contain', 'test-file.pdf');
  });
});
